def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Split off build metadata (ignore it)
        v = v.split('+')[0]

        # Split into core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v
            prerelease_parts = None

        # Parse core version
        major, minor, patch = map(int, core.split('.'))

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre_a, pre_b):
        # If both have no pre-release, they're equal
        if pre_a is None and pre_b is None:
            return 0

        # A version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare pre-release identifiers one by one
        for i in range(max(len(pre_a), len(pre_b))):
            # If one version ran out of identifiers, it has lower precedence
            if i >= len(pre_a):
                return -1
            if i >= len(pre_b):
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if identifiers are numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            # Numeric identifiers compare numerically
            if is_num_a and is_num_b:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            # Numeric has lower precedence than non-numeric
            elif is_num_a:
                return -1
            elif is_num_b:
                return 1
            # Non-numeric identifiers compare in ASCII order
            else:
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major.minor.patch
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare pre-release versions
    return compare_prerelease(pre_a, pre_b)

